#!/usr/bin/env bash
# Generated by Agent Team Kit 0.8.0. Do not edit: fixes go upstream, settings go in .agent-team/config.sh.
# Nightly janitor for the team machine. Safe to run any time; frees disk and stuck slots.
# Add project-specific cleanup (stop build daemons, shut down simulators) in a janitor_extra function in
# .agent-team/config.sh.
set -uo pipefail
# shellcheck source=lib.sh
. "$(cd "$(dirname "$0")" && pwd)/lib.sh"
at_init
cd "$AT_ROOT" || exit 1

echo "== git worktree prune"; git worktree prune 2>/dev/null || true
echo "== lock slots whose owner is gone"
for pid in "${AGENT_TEAM_LOCK_ROOT:-$AT_HOME/locks}"/*/slot-*/pid; do
  [ -f "$pid" ] || continue
  kill -0 "$(cat "$pid" 2>/dev/null)" 2>/dev/null || { rm -rf "$(dirname "$pid")"; echo "   freed $(dirname "$pid")"; }
done
echo "== merge-gate logs older than 14 days"; find .merge-gate -type f -mtime +14 -delete 2>/dev/null || true
echo "== event log kept to the last ${AGENT_TEAM_LOG_KEEP:-20000} lines"
log="$AT_HOME/events.jsonl"
if [ -f "$log" ]; then tail -n "${AGENT_TEAM_LOG_KEEP:-20000}" "$log" >"$log.tmp" && mv "$log.tmp" "$log"; fi
if declare -F janitor_extra >/dev/null; then echo "== janitor_extra"; janitor_extra || true; fi
echo "janitor done $(date)"
